"""Independent archive/content binding checks using small generated byte fixtures."""

import gzip
from dataclasses import replace
from hashlib import sha256

import pytest

from cloudsecops_live.contracts import Limits
from cloudsecops_live.errors import EvidenceError
from cloudsecops_live.integrations.aws_cloudtrail.collection import (
    ObjectVersion,
    RetrievedLog,
    require_authenticated,
)
from cloudsecops_live.integrations.aws_cloudtrail.models import AwsLog
from cloudsecops_live.integrations.aws_cloudtrail.validation import (
    CheckOutcome,
    ControlledValidation,
    DigestMember,
    assess_digest,
)
from tests.aws_helpers import BASE_TIME, scope


def candidate(content=b'{"Records":[]}'):
    """Author both byte domains independently of production parsing helpers."""
    configured = scope()
    packed = gzip.compress(content, mtime=0)
    log = AwsLog(packed, content, sha256(packed).hexdigest(), sha256(content).hexdigest(), ())
    reference = ObjectVersion(
        configured.bucket,
        configured.log_prefix + "2026/01/01/local-only.json.gz",
        "fictional-version-one",
        len(packed),
        BASE_TIME,
    )
    obj = RetrievedLog(reference, log, BASE_TIME, BASE_TIME)
    receipt = ControlledValidation(
        "controlled-local-only",
        0,
        CheckOutcome.VALID,
        CheckOutcome.VALID,
        CheckOutcome.VALID,
        (DigestMember(reference.bucket, reference.key, reference.version_id, log.content_sha256),),
        True,
        True,
    )
    return obj, receipt


def with_archive(obj, packed):
    return replace(
        obj,
        reference=replace(obj.reference, size=len(packed)),
        log=replace(obj.log, archive_bytes=packed, archive_sha256=sha256(packed).hexdigest()),
    )


def assert_invalid(assessment, reason):
    assert assessment.state == "invalid"
    assert assessment.reason == reason
    assert assessment.consistency_passed is False
    assert assessment.authenticated is False
    with pytest.raises(EvidenceError, match="^AWS_AUTHENTICATION_UNAVAILABLE$"):
        require_authenticated(assessment)


def test_unrelated_valid_gzip_cannot_borrow_matching_retained_content_and_digest():
    obj, receipt = candidate()
    changed = with_archive(obj, gzip.compress(b"unrelated private candidate bytes", mtime=0))
    assert changed.log.archive_sha256 == sha256(changed.log.archive_bytes).hexdigest()
    assert changed.log.content_sha256 == receipt.members[0].content_sha256
    assert_invalid(assess_digest(changed, receipt), "AWS_ARCHIVE_CONTENT_MISMATCH")


def test_replacing_content_and_its_member_hash_does_not_rebind_the_original_archive():
    obj, receipt = candidate()
    changed_content = b'{"Records":[],"forged-local-field":true}'
    changed_hash = sha256(changed_content).hexdigest()
    changed = replace(
        obj, log=replace(obj.log, content_bytes=changed_content, content_sha256=changed_hash)
    )
    forged_receipt = replace(
        receipt, members=(replace(receipt.members[0], content_sha256=changed_hash),)
    )
    assert_invalid(assess_digest(changed, forged_receipt), "AWS_ARCHIVE_CONTENT_MISMATCH")


@pytest.mark.parametrize(
    "damage",
    ["not-gzip", "empty", "header-only", "truncated", "crc", "isize", "junk", "concat"],
)
def test_rehashed_malformed_archive_never_passes_local_consistency(damage):
    obj, receipt = candidate()
    packed = obj.log.archive_bytes
    if damage == "not-gzip":
        packed = b"private non-gzip candidate"
    elif damage == "empty":
        packed = b""
    elif damage == "header-only":
        packed = packed[:10]
    elif damage == "truncated":
        packed = packed[:-1]
    elif damage == "crc":
        packed = packed[:-8] + bytes([packed[-8] ^ 1]) + packed[-7:]
    elif damage == "isize":
        packed = packed[:-4] + bytes([packed[-4] ^ 1]) + packed[-3:]
    elif damage == "junk":
        packed += b"private trailing bytes"
    else:
        packed += gzip.compress(b"another member", mtime=0)
    assert_invalid(assess_digest(with_archive(obj, packed), receipt), "AWS_ARCHIVE_INVALID")


def test_exact_compressed_and_expanded_limits_preserve_pending_unauthenticated_result():
    obj, receipt = candidate()
    limits = Limits(
        max_compressed_bytes=len(obj.log.archive_bytes),
        max_expanded_bytes=len(obj.log.content_bytes),
    )
    result = assess_digest(obj, receipt, limits=limits)
    assert result.state == "pending_source_authentication"
    assert result.reason == "AWS_AUTHENTICATION_UNAVAILABLE"
    assert result.consistency_passed is True
    assert result.authenticated is False
    with pytest.raises(EvidenceError, match="^AWS_AUTHENTICATION_UNAVAILABLE$"):
        require_authenticated(result)


@pytest.mark.parametrize("domain", ["compressed", "expanded"])
def test_one_byte_over_either_limit_is_invalid_even_with_matching_hashes(domain):
    obj, receipt = candidate()
    limits = Limits(
        max_compressed_bytes=len(obj.log.archive_bytes) - (domain == "compressed"),
        max_expanded_bytes=len(obj.log.content_bytes) - (domain == "expanded"),
    )
    assert_invalid(assess_digest(obj, receipt, limits=limits), "AWS_ARCHIVE_INVALID")


def test_high_ratio_archive_cannot_expand_past_small_bound_to_reach_mismatch_check():
    obj, receipt = candidate()
    packed = gzip.compress(b"X" * 8192, mtime=0)
    changed = with_archive(obj, packed)
    limits = Limits(max_compressed_bytes=len(packed), max_expanded_bytes=64)
    assert len(obj.log.content_bytes) < limits.max_expanded_bytes
    assert_invalid(assess_digest(changed, receipt, limits=limits), "AWS_ARCHIVE_INVALID")


@pytest.mark.parametrize("wrong", [None, {}, True, object()])
def test_untyped_or_unbounded_limits_are_not_an_accepted_validation_contract(wrong):
    obj, receipt = candidate()
    with pytest.raises(EvidenceError, match="^AWS_VALIDATION_RECEIPT$"):
        assess_digest(obj, receipt, limits=wrong)


@pytest.mark.parametrize("wrong", [None, {}, object()])
def test_nested_log_must_be_the_typed_local_evidence_contract(wrong):
    obj, receipt = candidate()
    with pytest.raises(EvidenceError, match="^AWS_VALIDATION_RECEIPT$"):
        assess_digest(replace(obj, log=wrong), receipt)


@pytest.mark.parametrize("wrong", [None, {}, object()])
def test_nested_reference_must_be_the_typed_version_contract(wrong):
    obj, receipt = candidate()
    with pytest.raises(EvidenceError, match="^AWS_VALIDATION_RECEIPT$"):
        assess_digest(replace(obj, reference=wrong), receipt)


@pytest.mark.parametrize("wrong", [None, True, "33"])
def test_reference_size_cannot_be_missing_truthy_or_coerced_text(wrong):
    obj, receipt = candidate()
    changed = replace(obj, reference=replace(obj.reference, size=wrong))
    with pytest.raises(EvidenceError, match="^AWS_VALIDATION_RECEIPT$"):
        assess_digest(changed, receipt)


@pytest.mark.parametrize(
    "changes",
    [{"is_delete_marker": True}, {"is_latest": False}, {"version_id": "null"}],
)
def test_unsupported_reference_states_cannot_pass_archive_consistency(changes):
    obj, receipt = candidate()
    changed = replace(obj, reference=replace(obj.reference, **changes))
    assert_invalid(assess_digest(changed, receipt), "AWS_ARCHIVE_INVALID")


@pytest.mark.parametrize("field", ["archive_bytes", "content_bytes"])
@pytest.mark.parametrize("wrong", [None, "not bytes", bytearray(b"x"), memoryview(b"x")])
def test_non_bytes_evidence_fields_fail_with_fixed_receipt_error(field, wrong):
    obj, receipt = candidate()
    with pytest.raises(EvidenceError, match="^AWS_VALIDATION_RECEIPT$"):
        assess_digest(replace(obj, log=replace(obj.log, **{field: wrong})), receipt)


def test_declared_archive_size_must_match_retained_exact_byte_count():
    obj, receipt = candidate()
    changed = replace(obj, reference=replace(obj.reference, size=obj.reference.size + 1))
    assert_invalid(assess_digest(changed, receipt), "AWS_ARCHIVE_INVALID")


def test_recompressed_identical_content_can_pass_consistency_without_authentication():
    obj, receipt = candidate()
    changed = with_archive(obj, gzip.compress(obj.log.content_bytes, mtime=1))
    assert changed.log.archive_bytes != obj.log.archive_bytes
    result = assess_digest(changed, receipt)
    assert result.consistency_passed is True
    assert result.state == "pending_source_authentication"
    assert result.authenticated is False
    with pytest.raises(EvidenceError, match="^AWS_AUTHENTICATION_UNAVAILABLE$"):
        require_authenticated(result)
